import { Group, Mesh, MeshBasicMaterial, MeshPhysicalMaterial, MeshStandardMaterial, SphereGeometry, CylinderGeometry, PlaneGeometry, Color } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
    const root = new Group();
    if (config.position) root.position.fromArray(config.position);
    if (config.rotation) root.rotation.fromArray(config.rotation);
    if (config.scale) root.scale.fromArray(config.scale);

    // ---------- Load primary gear ----------
    const gltf = ctx.glbLoader(config.assets?.meshUrl ?? '');
    const primaryGear = gltf.scene ? gltf.scene.clone() : new Group();
    root.add(primaryGear);

    // ---------- Secondary gear ----------
    const secondaryGear = primaryGear.clone();
    const secondaryScale = 0.9 / 1.6; // relative to primary 1.6‑unit diameter
    secondaryGear.scale.setScalar(secondaryScale);
    secondaryGear.position.set(1.15, 0.35, -0.1);
    root.add(secondaryGear);

    // ---------- Jewel pivot ----------
    const jewelMaterial = new MeshPhysicalMaterial({
        color: new Color('#ff2a38'),
        transmission: 0.6,
        ior: 1.76,
        emissive: new Color('#ff2a38'),
        emissiveIntensity: 1.8,
        roughness: 0.5,
        metalness: 0.0
    });
    const jewel = new Mesh(new SphereGeometry(0.12, 32, 32), jewelMaterial);
    root.add(jewel);

    // ---------- Arbor shafts ----------
    const shaftMaterial = new MeshStandardMaterial({ color: new Color('#16161d') });
    const shaftGeometry = new CylinderGeometry(0.05, 0.05, 0.8, 16);
    const createShaft = (pos) => {
        const shaft = new Mesh(shaftGeometry, shaftMaterial);
        shaft.rotation.x = Math.PI / 2; // align with Z
        shaft.position.copy(pos);
        return shaft;
    };
    root.add(createShaft(new THREE.Vector3(0, 0, 0)));
    root.add(createShaft(new THREE.Vector3(1.15, 0.35, -0.1)));

    // ---------- Contact shadow ellipse ----------
    const shadowMaterial = new MeshBasicMaterial({
        color: new Color('#0b0b10'),
        transparent: true,
        opacity: 0.5,
        depthWrite: false
    });
    const shadowPlane = new Mesh(new PlaneGeometry(2.6, 1.2), shadowMaterial);
    shadowPlane.position.set(0, -1.2, 0.01);
    root.add(shadowPlane);

    // ---------- Backdrop plane ----------
    const backdropMaterial = new MeshBasicMaterial({ color: new Color('#14141a') });
    const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMaterial);
    backdrop.position.set(0, 0, -3);
    root.add(backdrop);

    // ---------- Animations ----------
    const timelines = [];

    // primary gear rotation (0.08 rad/s)
    const primaryDuration = (2 * Math.PI) / 0.08;
    timelines.push(
        gsap.to(primaryGear.rotation, {
            y: `+=${2 * Math.PI}`,
            duration: primaryDuration,
            repeat: -1,
            ease: 'none'
        })
    );

    // secondary gear opposite rotation (‑0.142 rad/s)
    const secondaryDuration = (2 * Math.PI) / 0.142;
    timelines.push(
        gsap.to(secondaryGear.rotation, {
            y: `-=${2 * Math.PI}`,
            duration: secondaryDuration,
            repeat: -1,
            ease: 'none'
        })
    );

    // ---------- Cinematic primitives ----------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const fn = ctx.primitives?.[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        }
    }

    // ---------- Text content ----------
    const createTextMesh = (text, style, yPos) => {
        if (ctx.fontAtlas && typeof ctx.fontAtlas.createText === 'function') {
            const mesh = ctx.fontAtlas.createText(text, {
                ...style,
                atlasRegion: { atlas: 0, x: 0, y: 0, width: 512, height: 320 }
            });
            mesh.position.set(0, yPos, 0.02);
            return mesh;
        }
        // fallback placeholder
        const placeholder = new Group();
        placeholder.position.set(0, yPos, 0.02);
        return placeholder;
    };

    const headlineSpec = config.textContent?.find(t => t.role === 'headline') || { text: 'The going train' };
    const captionSpec = config.textContent?.find(t => t.role === 'caption') || { text: '34 COMPONENTS / HAND-FINISHED' };

    const headline = createTextMesh(
        headlineSpec.text,
        {
            fontFamily: 'Lora',
            fontSize: 68,
            fontWeight: 600,
            letterSpacing: -0.005,
            lineHeight: 1.1,
            color: '#e8ecf2'
        },
        -1.7
    );
    const caption = createTextMesh(
        captionSpec.text,
        {
            fontFamily: 'JetBrains Mono',
            fontSize: 18,
            fontWeight: 400,
            letterSpacing: 0.08,
            lineHeight: 1.4,
            color: '#e8ecf2'
        },
        -2.1
    );

    root.add(headline);
    root.add(caption);

    // ---------- Cleanup ----------
    root.userData.handlers = {};
    root.userData.cleanup = () => {
        timelines.forEach(t => t.kill());

        const disposeNode = (obj) => {
            if (obj.isMesh) {
                obj.geometry?.dispose();
                if (Array.isArray(obj.material)) {
                    obj.material.forEach(m => m.dispose());
                } else {
                    obj.material?.dispose();
                }
            }
        };

        primaryGear.traverse(disposeNode);
        secondaryGear.traverse(disposeNode);
        jewel.traverse(disposeNode);
        shadowPlane.traverse(disposeNode);
        backdrop.traverse(disposeNode);
        // shafts share geometry/material already disposed above
    };

    return root;
}
